'use client'
import { useState, useEffect } from 'react'
import { createClient } from '@/lib/supabase/client'
import { useRouter } from 'next/navigation'

export default function AgendaReservas() {
  const supabase = createClient()
  const router = useRouter()
  const [reservas, setReservas] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [fechaFiltro, setFechaFiltro] = useState(new Date().toISOString().split('T')[0])

  useEffect(() => {
    fetchReservas()
  }, [fechaFiltro])

  const fetchReservas = async () => {
    setLoading(true)
    const { data, error } = await supabase
      .from('reservas')
      .select(`
        *,
        canchas (nombre, tipo)
      `)
      .eq('fecha', fechaFiltro)
      .order('hora_inicio', { ascending: true })

    if (!error) setReservas(data || [])
    setLoading(false)
  }

  const actualizarEstado = async (id: string, nuevoEstado: string) => {
    const { error } = await supabase
      .from('reservas')
      .update({ estado: nuevoEstado })
      .eq('id', id)
    
    if (!error) fetchReservas()
  }

  return (
    <main className="min-h-screen bg-slate-900 text-white p-4 md:p-8 font-sans">
      <div className="max-w-6xl mx-auto">
        
        {/* HEADER SaaS */}
        <header className="flex flex-col md:flex-row justify-between items-center mb-8 gap-6 bg-slate-800 p-6 rounded-[32px] border border-slate-700 shadow-xl">
          <div>
            <button onClick={() => router.push('/dashboard')} className="text-green-400 text-xs font-black uppercase tracking-widest mb-2 block hover:underline">
              ← Panel de Control
            </button>
            <h1 className="text-3xl font-black italic uppercase tracking-tighter">
              Agenda de <span className="text-green-500">Turnos</span>
            </h1>
          </div>

          <div className="flex items-center gap-4 bg-slate-900 p-2 rounded-2xl border border-slate-700">
            <span className="text-xs font-bold px-3 text-slate-400 uppercase">Día:</span>
            <input 
              type="date" 
              value={fechaFiltro}
              onChange={(e) => setFechaFiltro(e.target.value)}
              className="bg-transparent font-bold text-green-500 outline-none"
            />
          </div>
        </header>

        {/* TABLA DE TURNOS */}
        <div className="bg-slate-800 rounded-[32px] border border-slate-700 overflow-hidden shadow-2xl">
          {loading ? (
            <div className="p-20 text-center text-slate-500 font-bold uppercase tracking-widest animate-pulse">Cargando turnos...</div>
          ) : reservas.length > 0 ? (
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900/50 border-b border-slate-700 text-[10px] font-black uppercase tracking-widest text-slate-500">
                    <th className="p-6">Hora</th>
                    <th className="p-6">Cancha</th>
                    <th className="p-6">Cliente</th>
                    <th className="p-6">Monto</th>
                    <th className="p-6">Estado</th>
                    <th className="p-6 text-right">Acciones</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-700">
                  {reservas.map((res) => (
                    <tr key={res.id} className="hover:bg-white/5 transition-colors">
                      <td className="p-6 font-black text-xl text-green-500 italic">{res.hora_inicio.slice(0,5)}</td>
                      <td className="p-6">
                        <span className="font-bold text-white block">{res.canchas?.nombre}</span>
                        <span className="text-[10px] bg-slate-700 px-2 py-0.5 rounded text-slate-400 uppercase">{res.canchas?.tipo}</span>
                      </td>
                      <td className="p-6">
                        <span className="font-bold block text-white">{res.cliente_nombre}</span>
                        <span className="text-xs text-slate-500 italic">{res.cliente_telefono}</span>
                      </td>
                      <td className="p-6 font-bold text-white">${res.monto_total}</td>
                      <td className="p-6">
                        <span className={`text-[10px] font-black px-3 py-1 rounded-full uppercase ${
                          res.estado === 'confirmada' ? 'bg-green-500/20 text-green-500' : 
                          res.estado === 'pendiente' ? 'bg-yellow-500/20 text-yellow-500' : 'bg-red-500/20 text-red-500'
                        }`}>
                          {res.estado}
                        </span>
                      </td>
                      <td className="p-6 text-right">
                        <div className="flex justify-end gap-2">
                          <button 
                            onClick={() => actualizarEstado(res.id, 'confirmada')}
                            className="bg-green-600 hover:bg-green-500 p-2 rounded-lg text-white transition-all text-xs font-bold"
                          >
                            ✓
                          </button>
                          <button 
                            onClick={() => actualizarEstado(res.id, 'cancelada')}
                            className="bg-red-600/20 hover:bg-red-600 p-2 rounded-lg text-red-500 hover:text-white transition-all text-xs font-bold"
                          >
                            ✕
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="p-20 text-center">
              <span className="text-5xl block mb-4">🏜️</span>
              <p className="text-slate-500 font-bold uppercase tracking-widest text-sm">No hay reservas para este día</p>
            </div>
          )}
        </div>

        {/* RESUMEN RÁPIDO */}
        <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-green-600 p-6 rounded-[28px] shadow-lg shadow-green-900/20">
            <p className="text-green-200 text-xs font-black uppercase tracking-widest mb-1">Total del día</p>
            <h3 className="text-3xl font-black text-white italic">
              ${reservas.reduce((acc, curr) => acc + (curr.estado !== 'cancelada' ? curr.monto_total : 0), 0)}
            </h3>
          </div>
          <div className="bg-slate-800 p-6 rounded-[28px] border border-slate-700">
            <p className="text-slate-500 text-xs font-black uppercase tracking-widest mb-1">Turnos Confirmados</p>
            <h3 className="text-3xl font-black text-white italic">
              {reservas.filter(r => r.estado === 'confirmada').length}
            </h3>
          </div>
          <div className="bg-slate-800 p-6 rounded-[28px] border border-slate-700">
            <p className="text-slate-500 text-xs font-black uppercase tracking-widest mb-1">Pendientes de Seña</p>
            <h3 className="text-3xl font-black text-white italic text-yellow-500">
              {reservas.filter(r => r.estado === 'pendiente').length}
            </h3>
          </div>
        </div>
      </div>
    </main>
  )
}